func (c *Config) Validate() error {
	var problems []string
	bad := func(format string, args ...any) { problems = append(problems, fmt.Sprintf(format, args...)) }
	pos := func(key string, v float64) {
		if v <= 0 {
			bad("%s 는 0 보다 커야 합니다 (현재 %g)", key, v)
		}
	}
	nonNeg := func(key string, v float64) {
		if v < 0 {
			bad("%s 는 0 이상이어야 합니다 (현재 %g)", key, v)
		}
	}

	if c.Mode != "paper" && c.Mode != "live" {
		bad("QUANTOSS_MODE 는 paper 또는 live 여야 합니다 (현재 %q)", c.Mode)
	}
	pos("QUANTOSS_BUDGET_KRW", c.BudgetKRW)
	if c.RiskPerTradePct <= 0 || c.RiskPerTradePct > 10 {
		bad("QUANTOSS_RISK_PER_TRADE_PCT 는 0 초과 10 이하여야 합니다 (현재 %g) — 한 거래에 자본의 10%% 넘게 걸지 마세요",
			c.RiskPerTradePct)
	}
	if c.MaxPositionPct <= 0 || c.MaxPositionPct > 100 {
		bad("QUANTOSS_MAX_POSITION_PCT 는 0 초과 100 이하여야 합니다 (현재 %g)", c.MaxPositionPct)
	}
	if c.DailyLossLimitPct <= 0 || c.DailyLossLimitPct > 100 {
		bad("QUANTOSS_DAILY_LOSS_LIMIT_PCT 는 0 초과 100 이하의 '크기' 여야 합니다 (현재 %g) — -3 이 아니라 3 으로 적으세요",
			c.DailyLossLimitPct)
	}
	if c.MaxPositions < 1 {
		bad("QUANTOSS_MAX_POSITIONS 는 1 이상이어야 합니다 (현재 %d)", c.MaxPositions)
	}
	if c.MaxConsecutiveLosses < 1 {
		bad("QUANTOSS_MAX_CONSECUTIVE_LOSSES 는 1 이상이어야 합니다 (현재 %d)", c.MaxConsecutiveLosses)
	}
	if c.MaxTradesPerDay < 1 {
		bad("QUANTOSS_MAX_TRADES_PER_DAY 는 1 이상이어야 합니다 (현재 %d)", c.MaxTradesPerDay)
	}

	if c.ORBMinutes < 1 {
		bad("QUANTOSS_ORB_MINUTES 는 1 이상이어야 합니다 (현재 %d)", c.ORBMinutes)
	}
	pos("QUANTOSS_ATR_STOP_MULT", c.ATRStopMult)
	pos("QUANTOSS_REWARD_RISK", c.RewardRisk)
	pos("QUANTOSS_SURGE_VOL_MULT", c.SurgeVolMult)
	nonNeg("QUANTOSS_SCALE_OUT_R", c.ScaleOutR)
	nonNeg("QUANTOSS_TRAIL_ATR_MULT", c.TrailATRMult)
	nonNeg("QUANTOSS_PROFIT_LOCK_PCT", c.ProfitLockPct)
	if c.ScaleOutR > 0 && c.RewardRisk > 0 && c.ScaleOutR >= c.RewardRisk {
		bad("QUANTOSS_SCALE_OUT_R(%g) 는 QUANTOSS_REWARD_RISK(%g) 보다 작아야 합니다 — 익절 목표에 먼저 닿으면 절반 익절이 동작하지 않습니다",
			c.ScaleOutR, c.RewardRisk)
	}

	// 장중 시각 순서: 개장 ≤ 진입 시작 < 진입 종료 ≤ 강제 청산
	if c.SessionOpen.Minutes() > c.EntryStart.Minutes() {
		bad("QUANTOSS_ENTRY_START(%s) 는 개장 시각(%s) 이후여야 합니다", c.EntryStart, c.SessionOpen)
	}
	if c.EntryStart.Minutes() >= c.EntryEnd.Minutes() {
		bad("QUANTOSS_ENTRY_START(%s) 는 QUANTOSS_ENTRY_END(%s) 보다 빨라야 합니다", c.EntryStart, c.EntryEnd)
	}
	if c.EntryEnd.Minutes() > c.FlattenAt.Minutes() {
		bad("QUANTOSS_ENTRY_END(%s) 는 QUANTOSS_FLATTEN_AT(%s) 이전이어야 합니다 — 청산 직전 진입은 금지", c.EntryEnd, c.FlattenAt)
	}

	if c.UniverseSize < 1 {
		bad("QUANTOSS_UNIVERSE_SIZE 는 1 이상이어야 합니다 (현재 %d)", c.UniverseSize)
	}
	pos("QUANTOSS_MIN_PRICE", c.MinPrice)
	if c.MinPrice >= c.MaxPrice {
		bad("QUANTOSS_MIN_PRICE(%g) 는 QUANTOSS_MAX_PRICE(%g) 보다 작아야 합니다", c.MinPrice, c.MaxPrice)
	}

	if c.CommissionRate < 0 || c.CommissionRate > 0.05 {
		bad("QUANTOSS_COMMISSION_RATE 는 0 이상 0.05 이하의 '비율' 이어야 합니다 (현재 %g) — 0.015%% 는 0.00015", c.CommissionRate)
	}
	if c.SellTaxRate < 0 || c.SellTaxRate > 0.05 {
		bad("QUANTOSS_SELL_TAX_RATE 는 0 이상 0.05 이하의 '비율' 이어야 합니다 (현재 %g) — 0.15%% 는 0.0015", c.SellTaxRate)
	}
	if c.SlippageBps < 0 || c.SlippageBps > 1000 {
		bad("QUANTOSS_SLIPPAGE_BPS 는 0 이상 1000 이하여야 합니다 (현재 %g)", c.SlippageBps)
	}

	// PollSeconds < 1 이면 티커가 패닉하거나 API 를 과도하게 호출해 차단당한다.
	if c.PollSeconds < 1 || c.PollSeconds > 60 {
		bad("QUANTOSS_POLL_SECONDS 는 1 이상 60 이하여야 합니다 (현재 %g)", c.PollSeconds)
	}
	if c.DataDir == "" {
		bad("DataDir 이 비어 있습니다")
	}
	if c.MaxCorrelation < 0 || c.MaxCorrelation > 1 {
		bad("QUANTOSS_MAX_CORRELATION 은 0(끔) 이상 1 이하여야 합니다 (현재 %g)", c.MaxCorrelation)
	}
	if c.DataStallSeconds < 1 {
		bad("QUANTOSS_DATA_STALL_SECONDS 는 1 이상이어야 합니다 (현재 %d)", c.DataStallSeconds)
	}
	if c.DataFatalSeconds <= c.DataStallSeconds {
		bad("QUANTOSS_DATA_FATAL_SECONDS(%d) 는 QUANTOSS_DATA_STALL_SECONDS(%d) 보다 커야 합니다",
			c.DataFatalSeconds, c.DataStallSeconds)
	}
	if c.ReconcileSeconds < 1 {
		bad("QUANTOSS_RECONCILE_SECONDS 는 1 이상이어야 합니다 (현재 %d)", c.ReconcileSeconds)
	}

	if len(problems) == 0 {
		return nil
	}
	return fmt.Errorf("설정 오류 %d건:\n  - %s", len(problems), strings.Join(problems, "\n  - "))
}

// VersionHash: 성과에 영향을 주는 전략·리스크·진입/청산 설정의 해시 (8 hex). 청산 레코드에 기록되어
// "이 버전이 배포된 뒤의 포지션" 만 모은 전진 검증 표본(forward)을 만든다. 설정이 바뀌면 해시가 바뀌고 전진 표본은 새로 시작한다.
func (c *Config) VersionHash() string {
	v := struct {
		Market, Strategy, USStrategy, PaperStrategy, EntryMode, Profile                                                               string
		VWAPExit                                                                                                                      bool
		Breakeven                                                                                                                     bool
		TargetR, TightenFac                                                                                                           float64
		TightenBars                                                                                                                   int
		RiskPct, MaxLoss, MaxPosPct, DailyLoss, WeeklyLoss, MinStop, MinStopCost, ScaleOut, Trail, GapPull, GapVol, MaxDayGain, Drift float64
		MaxPos, MaxTrades, MaxConsec, ConfirmBars, RetestBars, TimeStop, Preselect                                                    int
	}{c.Market, c.Strategy, c.USStrategy, c.PaperStrategy, c.EntryMode, c.RiskProfile, c.ExitVWAPCross, c.Breakeven, c.ExitTargetR, c.TrailTightenFactor, c.TrailTightenBars,
		c.RiskPerTradePct, c.MaxLossPerTrade(), c.MaxPositionPct, c.DailyLossLimitPct, c.WeeklyLossLimitPct, c.MinStopPct, c.MinStopCostMult, c.ScaleOutR, c.TrailATRMult, c.GapPullMin, c.GapVolMult, c.MaxDayGainPct, c.DriftHaltR,
		c.MaxPositions, c.MaxTradesPerDay, c.MaxConsecutiveLosses, c.ConfirmBars, c.RetestBars, c.TimeStopBars, c.Preselect}
	b, _ := json.Marshal(v)
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])[:8]
}

// ResearchMarketList: 연구·누적 대상 시장 목록.
func (c *Config) ResearchMarketList() []string {
	var out []string
	for _, m := range strings.Split(c.ResearchMarkets, ",") {
		if m = strings.TrimSpace(m); m == "KR" || m == "US" {
			out = append(out, m)
		}
	}
	if len(out) == 0 {
		return c.Markets()
	}
	return out
}
