		{"slack", c.SlackWebhook == "https://hooks"}, {"notifytrades", c.NotifyTrades}, {"entry", c.EntryStart == Clock{9, 20}},
	}
	for _, ck := range checks {
		if !ck.ok {
			t.Errorf("%s not parsed: %+v", ck.name, c)
		}
	}
